for(const [id,[en,zh]] of Object.entries(CONTENT_REPAIRS)){
 const w=WORDS.find(w=>w.id===id);if(!w)throw Error('Unknown repair '+id);
 if(!w.en)w.en=en;if(!w.zh)w.zh=zh;
 w.reviewIssues=(w.reviewIssues||[]).filter(issue=>issue!=='Meaning and translations absent from CSV');
}
function contentAudit(){return CHAPTERS.map(ch=>{const words=WORDS.filter(w=>inChapter(w,ch));return {ch,total:words.length,usable:words.filter(wordGameReady).length,unresolved:words.filter(w=>!wordGameReady(w)).length};});}
